# Personages: code -> (soort_fout, eigen_fout, wie_betaalt, zelfbedrog, daarna_doet)
P={
'PERS-corran':('bewondering voor de vijand','Corran ziet Hesta\'s omweg in de kerncode, vindt hem prachtig en gebruikt hem in de stemming als eigen bewijs in plaats van hem te melden.','hijzelf en de Dhurn (verbanning)','"Machines liegen niet, dus ik hoef het niet te zeggen."','Trekt naar de bergen en bouwt daar nooit meer iets moois.'),
'PERS-teo':('uitstel','Teo voelt al maanden de Lijn in zijn vingers en stelt het vertellen elke dag een dag uit; daardoor kan Liora voor hem beslissen. Strikt niet-seksueel.','hijzelf (zijn gave)','"Morgen zeg ik het."','Zegt nee tegen Liora als ze het eindelijk vraagt.'),
'PERS-aukje':('ijdelheid','Aukje weet dat de tweede staking niet te winnen is en zingt de vierhonderd vrouwen toch de pannen uit, omdat het lied van haar is.','de vrouwen die hun loon verliezen, en zijzelf','"Een lied is ook een overwinning."','Wordt opgehangen; het lied overleeft haar.'),
'PERS-joris':('eigenbelang','Joris kocht zijn eerste rustmaand door een stalgenoot aan te wijzen die wilde vluchten.','die stalgenoot (naam open)','"In een stal is iedereen een nummer, ook ik."','Turft de dagen sinds dat verraad op de muur.'),
'PERS-liane':('vroomheid als blindheid','In haar eerste tempeljaar gaf Liane een twijfelende jongere ontvangster aan: Joa, die in 245 wit als papier wordt gevonden.','Joa','"Ik heb haar geholpen geloven."','Houdt later zelf de lijst bij.'),
'PERS-ysel-handlezer':('nieuwsgierigheid','Ze leest de plaat hardop in de kluis, tegen het verbod van haar oudsten in, en het woord wekt iets.','de oude lezer naast haar, die zijn gehoor verliest','"Wie het niet hardop zegt, weet het niet echt."','Leert gebarentaal om met hem te praten.'),
'PERS-isa-doorgroeid':('wraakzucht','Isa publiceert het Hal-Neth-register met alle namen, ook die van families die zich verborgen hielden.','een Grauwendorp dat wordt opgehaald','"De waarheid kan niemand kwaad doen."','Gaat het dorp achterna om te helen wat ze brak.'),
'PERS-gidse-oevrin':('schaarste-denken','Zij verkoopt al jaren stukjes metaal uit de gang naar de lander; daarom stort hij in waar Liora hem nodig heeft.','een tweede gids (naam open)','"Eén stukje mist niemand."','Graaft met haar handen een nieuwe doorgang.'),
'PERS-krie':('trouw aan de doden','Krie maakt een barst in de steen om haar gebonden voorouders te bevrijden, en die doet ook de levende Orrim pijn.','haar moeder','"De doden hebben langer gewacht."','Zingt bij elke pijn mee, als boete.'),
'PERS-lirra':('eerzucht','Lirra meldt het signaal bij de Orde in plaats van bij haar volk, voor een plaats in Saelith.','de Skerra-klif, die daarna bewaakt wordt','"Van binnenuit kan ik meer."','Krijgt de plaats en kan er niets mee.'),
'PERS-tamsin':('overmoed','Tamsin neemt één tocht te veel met een te volle boot, omdat ze niet kan weigeren; de boot slaat om. Niet-seksueel (lekkinderen).','haar stuurvrouw','"Nog één keer gaat het goed."','Vaart voortaan alleen.'),
'PERS-nouri':('beschermende leugen','Nouri noemt de gaven-man van wie ze houdt als haar bron om hem te beschermen; juist daardoor wordt hij geregistreerd.','hij','"Wie nuttig is, wordt gespaard."','Vervalst niets, maar gaat het register in om hem eruit te praten.'),
'PERS-ida':('gemakzucht','Ida stopt met meten bij de derde klok omdat de getallen haar bang maken; het logboek heeft een gat van drie jaar.','de lekgeboorten die niemand verwacht','"Het Zegel hield achthonderd jaar, het houdt ook vannacht."','Meet daarna elk uur, te laat.'),
'PERS-zirr':('eigenmachtigheid','Zirr zegt "ik" en sluit een verdrag dat de drie korven niet willen.','de kleinste korf','"Iemand moest spreken."','Wordt door de korven gemeden en blijft het verdrag toch nakomen.'),
'PERS-ondal':('doodsangst','Om niet te sterven groeit Ondal door een ander levend lichaam heen dat nee zei; de Myrrhen beginnen met een genegeerd nee.','het lichaam dat nee zei','"Leven is altijd een ja."','Laat de Myrrhen bij elke binding eerst om toestemming vragen, zonder te zeggen waarom.'),
'PERS-orund':('koppigheid','Orund houdt de Amberpas dicht voor vluchtelingen uit Kharvos, ook voor de vrouwen, omdat zijn huid de oude geschiedenis draagt en niet de nieuwe.','de vluchtelingen aan de verkeerde kant','"Een pas die eenmaal open is, gaat nooit meer dicht."','Opent hem een winter te laat.'),
'PERS-lan':('weglopen','Lan vertrekt zonder de moeder te zeggen wat er komt; zij draagt de straf alleen.','de moeder','"Zonder mij is zij veiliger."','Komt twintig jaar later terug en wordt niet herkend.'),
'PERS-vaelorn':('neerbuigendheid','Vaelorn wist eeuwen wat het Zegel was en vertelde mensen een mooiere mythe, omdat de waarheid te zwaar voor ze zou zijn.','generaties die op een mythe bouwden','"Kinderen geef je een sprookje."','Moet in 801 de mythe zelf ontmantelen tegenover Liora.'),
}
